import {MarkdownText,MarkdownField} from './MarkdownText.jsx';
import {useModules} from '../modules/context.tsx';
import React,{useEffect,useState} from 'react';
import {useDraft} from './state.js';
import {SaveBar} from './ui.jsx';
import {Modal} from './preferences.tsx';
import {useWritingRequest} from './writing-request.js';
import {OrganizationPicker} from './OrganizationPicker.jsx';
import {useDialog} from '../dialog.tsx';
import {ChangeEditor,relationKinds,relationStyles,relationColors} from '../features/structure/Timeline.jsx';
import {EdgeEditor} from '../features/memory/EdgeEditor.jsx';
const affiliationDraft=data=>({ids:[...new Set(data.affiliations.map(e=>e.to))],nodeRevision:data.nodeRevision,edgeRevisions:Object.fromEntries(data.affiliations.map(e=>[e.id,e.revision])),organizationRevisions:Object.fromEntries(data.organizations.map(o=>[o.id,o.revision]))});
export function CardRelations({call,novelId,nodeId,data,busy,run,refresh,onEvent}){
 const modules=useModules();
 const write=useWritingRequest(call),{ask,confirm}=useDialog(),[editing,setEditing]=useState(null),[error,setError]=useState('');
 const {value,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:organization-links:${nodeId}`,affiliationDraft(data));
 useEffect(()=>{if(!dirty)accept(affiliationDraft(data));},[data]);
 const createOrg=async name=>{const title=await ask('新组织名称',name);if(!title?.trim())return;run(async()=>{const org=await write('writing.card.create',{novelId,type:'world_book',name:title.trim(),values:{'world:category':'组织'},reason:'作者从所属组织选择器新建组织'});change(old=>({...old,ids:[...old.ids,org.id],organizationRevisions:{...old.organizationRevisions,[org.id]:org.revision}}));refresh();});};
 const save=()=>run(async()=>{setError('');try{const next=await write('writing.affiliation.set',{novelId,nodeId,expectedNodeRevision:base.nodeRevision,edgeRevisions:base.edgeRevisions,organizationIds:value.ids,organizationRevisions:value.organizationRevisions,confirmed:true,reason:'作者选择基础所属组织'});accept(affiliationDraft(next));refresh();}catch(e){setError(e.message);throw e;}});
 const characters=data.edges.filter(e=>data.nodes.find(n=>n.id===(e.from===nodeId?e.to:e.from))?.type==='character_card');
 return <><section className="section-fold"><h3>所属组织</h3><p className="muted">选择组织世界书，保存后自动连线。这里编辑基础归属；随剧情变化可在关系图记录具体事件。</p><OrganizationPicker options={data.organizations} ids={value.ids} change={ids=>change(old=>({...old,ids}))} {...{busy}} onCreate={createOrg}/>{(dirty||error)&&<SaveBar {...{dirty,busy}} error={error||cacheError} onSave={save} label="保存组织关联"/>}{error&&<button disabled={busy} onClick={async()=>{if(await confirm('丢弃本次组织选择，重新读取最新连线？')){accept(affiliationDraft(await call('writing.cardRelations.get',{novelId,nodeId})));setError('');refresh();}}}>重新读取组织关联</button>}</section>
 <section className="section-fold"><div className="row"><h3 className="grow">人物关系</h3><button disabled={busy||!data.characters.length} onClick={()=>setEditing({kind:'new',data})}>＋ 添加人物关系</button></div>{!characters.length&&<p className="muted">选择已有角色，填写关系及生效位置；同一对人物可以有多种关系。</p>}{characters.map(edge=>{const changes=modules.evolution?data.changes.filter(c=>c.edgeId===edge.id):[];return <div className="structure-entry" key={edge.id} style={{borderLeft:`3px solid ${relationColors[edge.category||'other']}`}}><div className="row"><strong className="grow">{data.nodes.find(n=>n.id===(edge.from===nodeId?edge.to:edge.from))?.name} · {edge.name||'未命名关系'}</strong><button disabled={busy} onClick={()=>setEditing({kind:'edge',edge})}>编辑</button></div><small>{edge.baseActive!==false?'基础关系':edge.timing==='undated'&&!changes.length?'时间未定，尚不应用于阶段图':'从事件开始'} · {relationKinds[edge.category||'other']}</small>{edge.content&&<details><summary>关系说明</summary><MarkdownText text={edge.content}/></details>}{changes.map(c=><div className="row" key={c.id}><button onClick={()=>onEvent?.(c.eventId)}>{c.eventTitle}</button><span className="grow">{data.events.find(e=>e.id===c.eventId)?.planned?'计划 · ':''}{c.value.active?c.value.name||relationKinds[c.value.category]:'关系结束'}</span><button disabled={busy} onClick={()=>setEditing({kind:'change',change:c})}>修改变化</button></div>)}{modules.evolution&&<button disabled={busy||!data.events.length} onClick={()=>setEditing({kind:'change',change:{eventId:'',edgeId:edge.id,value:{name:edge.name,content:edge.content,category:edge.category||'other',style:edge.style||'solid',active:true},revision:0}})}>＋ 事件变化</button>}</div>;})}</section>
 {editing?.kind==='new'&&<NewRelationship {...{call,novelId,nodeId,busy,run}} data={editing.data} close={()=>setEditing(null)} saved={()=>{setEditing(null);refresh();}}/>}
 {editing?.kind==='edge'&&<Modal title="编辑基础关系" className="chapter-materials-modal" close={()=>setEditing(null)}><EdgeEditor {...{call,novelId,busy,run}} nodes={data.nodes} initial={editing.edge} saved={()=>{setEditing(null);refresh();}}/></Modal>}
 {modules.evolution&&editing?.kind==='change'&&<ChangeEditor {...{call,novelId,busy,run}} nodes={data.nodes} edges={data.edges} events={data.events} initial={editing.change} close={()=>setEditing(null)} saved={()=>{setEditing(null);refresh();}}/>}</>;
}
function NewRelationship({call,novelId,nodeId,data,busy,run,close,saved}){
 const write=useWritingRequest(call),initial={targetId:'',name:'',content:'',category:'other',style:'solid',timing:'base',eventId:'',nodeRevision:data.nodeRevision,characters:data.characters,events:data.events};
 const {value:v,change,accept,dirty,cacheError}=useDraft(`${novelId}:new-card-relationship:${nodeId}`,initial),[error,setError]=useState(''),set=(key,value)=>change(old=>({...old,[key]:value}));
 const save=()=>run(async()=>{setError('');try{await write('writing.relationship.create',{novelId,nodeId,expectedNodeRevision:v.nodeRevision,targetId:v.targetId,expectedTargetRevision:v.characters.find(c=>c.id===v.targetId)?.revision,name:v.name,content:v.content,category:v.category,style:v.style,timing:v.timing,eventId:v.eventId,expectedEventRevision:v.events.find(e=>e.id===v.eventId)?.revision,confirmed:true,reason:'作者从角色卡添加人物关系'});accept(initial);saved();}catch(e){setError(e.message);throw e;}});
 return <Modal title="添加人物关系" className="chapter-materials-modal" close={close}><div className="structure-form"><label>另一位角色<select aria-label="关系对象" value={v.targetId} onChange={e=>set('targetId',e.target.value)}><option value="">选择已有角色卡</option>{v.characters.map(c=><option key={c.id} value={c.id}>{c.name}{v.characters.filter(x=>x.name===c.name).length>1?` · ${c.id.slice(0,6)}`:''}</option>)}</select></label><label>关系名称<input aria-label="人物关系名称" value={v.name} placeholder="如：兄妹、师生、合作伙伴" onChange={e=>set('name',e.target.value)}/></label><label>类别<select aria-label="人物关系类别" value={v.category} onChange={e=>set('category',e.target.value)}>{Object.entries(relationKinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>生效位置<select aria-label="关系生效位置" value={v.timing} onChange={e=>set('timing',e.target.value)}><option value="base">基础关系（故事开始前已有）</option><option value="event">从具体事件开始</option><option value="undated">时间未定（稍后安排）</option></select></label>{v.timing==='event'&&<label>具体事件<select aria-label="人物关系起点事件" value={v.eventId} onChange={e=>set('eventId',e.target.value)}><option value="">选择时间线事件</option>{v.events.map(e=><option key={e.id} value={e.id}>{e.storyDate||e.storyTime} · {e.planned?'计划 · ':''}{e.title}</option>)}</select></label>}<label>线型<select value={v.style} onChange={e=>set('style',e.target.value)}>{Object.entries(relationStyles).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><MarkdownField label="说明" aria-label="人物关系说明" value={v.content} onChange={e=>set('content',e.target.value)}/><p className="muted">从事件开始的关系在此前隐藏；时间未定的关系先保留记录，安排事件后才进入阶段图。</p></div><SaveBar {...{dirty,busy}} error={error||cacheError} invalid={!v.targetId||!v.name.trim()||v.timing==='event'&&!v.eventId?'选择人物并填写关系、生效位置':null} onSave={save} label="保存人物关系"/>{error&&<button disabled={busy} onClick={()=>run(async()=>{const fresh=await call('writing.cardRelations.get',{novelId,nodeId});change(old=>({...old,nodeRevision:fresh.nodeRevision,characters:fresh.characters,events:fresh.events}));setError('');})}>保留填写内容，检查最新人物和事件版本</button>}</Modal>;
}
